-- every strength/cardio/mixed/skill row carries a loads_* tag or is on the loads-nothing list
INSERT INTO _0125_assert (ok) SELECT CASE WHEN (SELECT COUNT(*) FROM exercises e WHERE e.gym_id IS NULL AND e.is_active = 1 AND e.category IN ('strength', 'cardio', 'mixed', 'skill')
  AND NOT EXISTS (SELECT 1 FROM json_each(e.tags_json) WHERE value LIKE 'loads\_%' ESCAPE '\')
  AND e.slug NOT IN ('band-dead-bug', 'band-hip-abduction-standing', 'dead-bug', 'stability-ball-dead-bug', 'standing-bicycle', 'standing-hip-abduction')) = 0 THEN 1 ELSE 0 END;
-- every active row offers at least 2 substitutions that exist and are active
INSERT INTO _0125_assert (ok) SELECT CASE WHEN (SELECT COUNT(*) FROM exercises e WHERE e.gym_id IS NULL AND e.is_active = 1
  AND e.slug NOT IN ('12-minute-cooper-test')
  AND (SELECT COUNT(DISTINCT j.value) FROM json_each(COALESCE(NULLIF(e.alternatives_json, ''), '{"substitutions":[]}'), '$.substitutions') j
       JOIN exercises t ON t.slug = j.value AND t.is_active = 1 AND t.gym_id IS NULL) < 2) = 0 THEN 1 ELSE 0 END;
DROP TABLE _0125_assert;
